#!/usr/bin/env python3
"""Run C2 Unit08 recalibration with target-safe C2 length margin."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c2_unit08.py')
text=SOURCE.read_text(encoding='utf-8')
marker='UPDATES={'
assert text.count(marker)==1
EXTRA={
'ar-c2-u08-p01':"""وفي مراجعة أخيرة أعطت المؤرخة الطلاب فقرة من الإصدار المتأخر وحدها، ثم كشفت لهم بالتتابع مسودة مبكرة ورسالة معاصرة للحدث وسجلًا إداريًا مستقلًا. بعد كل كشف كتبوا ما الذي تغير في تفسيرهم، لا ما إذا أصبح الكاتب «موثوقًا» أو «غير موثوق». اتضح أن بعض التفاصيل بقيت مستقرة، بينما تغيرت درجة القوة في تفسير الدافع والتوقع. سجل الفريق هذه الحركة في جدول يبين أي مادة تعدل أي مقدمة من الحجة. بذلك أصبح تحديث الرأي تدريجيًا ومحددًا، بدل أن يؤدي العثور على مصدر جديد إلى قلب الثقة في النص كله دفعة واحدة.""",
'ar-c2-u08-p02':"""وفي فحص مستقل طلب الفريق من باحث آخر بناء صورة النشاط التجاري من مواد لم تدخل المجموعة الأصلية: سجلات عبور، إشارات إلى ديون، وشهادات عن نزاعات قصيرة. لم تنتج المواد وصفًا كاملًا، لكنها أعادت توزيع ما يبدو شائعًا ونادرًا. ثم سألوا أي نوع من المعاملات يترك أثرًا طويل العمر وأي نوع يختفي بسهولة. أضافوا إلى التقرير فقرة تذكر أن الغياب المتوقع يختلف حسب شكل النشاط، وأن قوة التعميم يجب أن تتبع هذه المعرفة. أصبح الأرشيف بذلك موضوعًا للنمذجة مثل الظاهرة نفسها، لا صندوقًا محايدًا نأخذ منه ما صادف أن بقي.""",
'ar-c2-u08-p03':"""وفي مراجعة ثانية استخدم الفريق صورًا ملتقطة قبل التدخل الأوسط وبعده مباشرة. أظهرت الصور أن بعض الخطوط التي تبدو اليوم قديمة أضيفت دفعة واحدة في تلك المرحلة، بينما بقيت أجزاء أخرى أقدم فعلًا. ثم طلبوا من طالب لا يعرف التواريخ ترتيب العناصر بحسب مظهرها فقط؛ أخطأ في عدة مواضع لأن الإضافة اللاحقة نُفذت بمهارة. استخدموا الخطأ التعليمي لتوضيح أن العين تستطيع وصف التشابه لكنها لا تؤرخ وحدها. كل حكم زمني يحتاج إلى سلسلة أدلة مادية ووثائقية، خصوصًا حين يكون هدف الإصلاح السابق هو صناعة استمرارية بصرية مقنعة.""",
'ar-c2-u08-p04':"""وفي اختبار إضافي أعطت المؤرخة الطلاب ثلاثة سجلات من مواقع مختلفة لكن من دون أسماء المواقع. طُلب منهم استنتاج نوع الأحداث التي يبدو كل سجل حساسًا لها. بعد كشف موضع كل كاتب اتضح أن أنماط التسجيل تتوافق بدرجة كبيرة مع اتجاه الرؤية ومهمة الجهة. لم يجعل ذلك الأرقام عديمة القيمة؛ سمح بإعادة تفسيرها باعتبارها بيانات مشروطة بمكان الملاحظة ونظام العمل. أضاف الفريق لذلك حقلًا ثابتًا لكل مصدر يصف ما الذي يستطيع رصده، وما الذي يمر غالبًا خارج انتباهه، وما نوع الصمت الذي سيكون مفاجئًا فعلًا لو وقع الحدث ولم يُذكر.""",
'ar-c2-u08-p05':"""وفي مراجعة أخيرة رسم الطلاب نسختين للحكاية: واحدة تبدأ من اليوم الشهير وأخرى تبدأ قبل عام. لم يطلب منهم اختيار الأطول، بل تحديد العلاقات التي تظهر أو تختفي في كل إطار. النسخة القصيرة أبرزت سرعة التنفيذ والتنسيق، والنسخة الطويلة كشفت تراكم الشروط والاختلاف بين المناطق. جمع الفريق الميزتين في سرد يبدأ بلحظة الإعلان ثم يعود إلى العمليات السابقة مع توضيح سبب الرجوع. هكذا حافظوا على وضوح القصة من دون أن يسمحوا لمركزها الزمني أن يعمل كسبب وحيد. صار اختيار البداية قرارًا حجاجيًا معلنًا يمكن مراجعته لا مجرد ترتيب قصصي بريء.""",
'ar-c2-u08-p06':"""وفي ختام التدريب أعطت المؤرخة كل طالب مصدرًا واحدًا وطلبت منه كتابة عبارة تبدأ بـ«هذا الدليل قوي من أجل...» وعبارة ثانية تبدأ بـ«ولا يكفي وحده من أجل...». أجبر التمرين الطلاب على تحديد وظيفة المادة بدل منحها درجة ثقة عامة. قد يكون السجل ممتازًا لتأريخ قرار وضعيفًا لمعرفة ما لم يره الكاتب، وقد تكون الذاكرة اللاحقة غنية لتاريخ التلقي وضعيفة لإثبات ما كان معروفًا في لحظة سابقة. عندما تتحدد الوظيفة يصبح الجمع بين المصادر أكثر دقة، لأن كل واحد يدخل الحجة في الموضع الذي يستطيع دعمه بدل أن تتنافس الوثائق على لقب المصدر الأفضل مطلقًا.""",
}
extra_code="EXTRA = "+repr(EXTRA)+"\nfor _pid,_extra in EXTRA.items():\n    ADD[_pid]=ADD[_pid].rstrip()+' '+_extra.strip()\n"
patched=text.replace(marker,extra_code+'\n'+marker,1)
exec(compile(patched,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
